CREATE TABLE "character_versions" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "character_versions_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"card_id" integer,
	"cast_member_id" integer,
	"number" integer,
	"label" text,
	"parent_version_id" integer,
	"lorebook_id" integer,
	"branch_id" integer,
	"year" integer,
	"month" integer,
	"day" integer,
	"history_entry_id" integer,
	"at_hour" integer,
	"at_minute" integer,
	"personal_position" integer,
	"source_session_id" integer,
	"source_message_id" integer,
	"written_by" text,
	"note" text,
	"lifted_from_amendment_id" integer,
	"valid_from_message_id" integer,
	"write_order" bigint NOT NULL,
	"retired_order" bigint,
	"name" text,
	"nickname" text,
	"aliases" text[] DEFAULT '{}'::text[] NOT NULL,
	"summary" text,
	"description" text,
	"personality" text,
	"scenario" text,
	"greetings" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"example_dialogues" text[] DEFAULT '{}'::text[] NOT NULL,
	"post_history_instructions" text,
	"creator_notes" jsonb,
	"strokes" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"face_media_id" integer,
	"likeness" jsonb,
	"timbre" jsonb,
	"sprite_set" text,
	"extensions" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"node_state" text,
	"node_visibility" text,
	"follows" text[] DEFAULT '{}'::text[] NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"updated_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "character_versions_one_owner_check" CHECK (("character_versions"."card_id" IS NULL) <> ("character_versions"."cast_member_id" IS NULL)),
	CONSTRAINT "character_versions_card_version_check" CHECK ("character_versions"."card_id" IS NULL OR ("character_versions"."number" IS NOT NULL AND cardinality("character_versions"."follows") = 0 AND "character_versions"."parent_version_id" IS NULL AND "character_versions"."lorebook_id" IS NULL AND "character_versions"."branch_id" IS NULL AND "character_versions"."year" IS NULL AND "character_versions"."history_entry_id" IS NULL AND "character_versions"."at_hour" IS NULL AND "character_versions"."personal_position" IS NULL AND "character_versions"."source_session_id" IS NULL AND "character_versions"."source_message_id" IS NULL AND "character_versions"."valid_from_message_id" IS NULL AND "character_versions"."node_state" IS NULL AND "character_versions"."node_visibility" IS NULL)),
	CONSTRAINT "character_versions_cast_version_check" CHECK ("character_versions"."cast_member_id" IS NULL OR ("character_versions"."number" IS NULL AND "character_versions"."lorebook_id" IS NOT NULL AND "character_versions"."node_state" IS NOT NULL AND "character_versions"."node_visibility" IS NOT NULL)),
	CONSTRAINT "character_versions_anchor_source_check" CHECK ("character_versions"."valid_from_message_id" IS NULL OR "character_versions"."source_session_id" IS NOT NULL),
	CONSTRAINT "character_versions_undated_base_check" CHECK ("character_versions"."cast_member_id" IS NULL OR "character_versions"."year" IS NOT NULL OR "character_versions"."source_session_id" IS NOT NULL OR ("character_versions"."branch_id" IS NULL AND "character_versions"."personal_position" IS NULL)),
	CONSTRAINT "character_versions_date_check" CHECK (("character_versions"."month" IS NOT NULL OR "character_versions"."day" IS NULL) AND ("character_versions"."year" IS NOT NULL OR "character_versions"."month" IS NULL))
);
